OUT_STYLES = 'src/data/accessory-styles.js'; OUT_CUSTOM = 'src/data/custom-cosmetics.js'
OUT = '#1a1208'
def FP(pts, fill, **k): k.setdefault('stroke', OUT); k.setdefault('sw', .9); return P(pts, fill, **k)
def FE(x, y, rx, ry, fill, **k): k.setdefault('stroke', OUT); k.setdefault('sw', .9); return E(x, y, rx, ry, fill, **k)
def FC(x, y, r, fill, **k): return FE(x, y, r, r, fill, **k)
def FR(x, y, w, h, fill, **k): k.setdefault('stroke', OUT); k.setdefault('sw', .9); return R(x, y, w, h, fill, **k)
def heart(x, y, s, fill, fill2=None, stroke=OUT, sw=.7):
    pts = []
    for i in range(18):
        t = i / 18 * 2 * math.pi
        hx = 16 * math.sin(t) ** 3; hy = -(13 * math.cos(t) - 5 * math.cos(2 * t) - 2 * math.cos(3 * t) - math.cos(4 * t))
        pts.append((x + hx / 16 * s, y + hy / 16 * s * 1.0 + s * .15))
    return P(pts, fill, stroke=stroke, sw=sw, smooth=True, fill2=fill2)
def eyewhite(x, y, rx=2.9, ry=2.7): return [FE(x, y, rx, ry, '#ffffff', sw=.7), C(x + .2, y + .1, 1.35, '#1a1208')]
def spiral(x, y, r, turns=2.5, stroke='#1a1208', sw=.7):
    pts = [(x + math.cos(i * .5) * r * i / (turns * 12.6), y + math.sin(i * .5) * r * i / (turns * 12.6)) for i in range(int(turns * 12.6) + 1)]
    return LN(pts, stroke, sw, smooth=True)

F = {}
def add(id, name, layers, price=None, rarity=None, old=False): F[id] = dict(id=id, name=name, layers=layers, price=price, rarity=rarity, old=old)

